<?php get_header();$search=isset($_GET['termen'])?sanitize_text_field(wp_unslash($_GET['termen'])):'';
$q=new WP_Query(['post_type'=>'glosar','posts_per_page'=>-1,'orderby'=>'title','order'=>'ASC','s'=>$search]);$groups=[];while($q->have_posts()){$q->the_post();$l=expedo_glossary_letter(get_the_title());$groups[$l][]=get_post();}wp_reset_postdata();ksort($groups);?><main class="site-shell" id="content"><?php expedo_render_breadcrumb([ ['label'=>'Glosar'] ]); ?><header class="page-heading"><div class="eyebrow">EXPEDO · GHID DE MOBILIER</div><h1>Glosar</h1><p>Termeni despre mobilier, materiale și amenajări interioare.</p></header><form class="glossary-search" method="get"><input type="search" name="termen" value="<?php echo esc_attr($search); ?>" placeholder="Caută un termen în glosar"><button type="submit">Caută</button><?php if($search):?><a href="<?php echo esc_url(get_post_type_archive_link('glosar'));?>">Resetează</a><?php endif;?></form><nav class="glossary-az"><?php foreach(range('A','Z') as $l):if(isset($groups[$l])):?><a href="#lit-<?php echo esc_attr($l);?>"><?php echo esc_html($l);?></a><?php else:?><span><?php echo esc_html($l);?></span><?php endif;endforeach;?></nav><?php foreach($groups as $l=>$posts):?><section class="glossary-group" id="lit-<?php echo esc_attr($l);?>"><h2><?php echo esc_html($l);?></h2><div class="glossary-terms"><?php foreach($posts as $p):?><a href="<?php echo esc_url(get_permalink($p));?>"><?php echo esc_html(get_the_title($p));?> <span>↗</span></a><?php endforeach;?></div></section><?php endforeach;?></main><?php get_footer();?>